namespace Tekus.Domain.Common;

/// <summary>
/// Base class for every domain entity. Identity is a <see cref="Guid"/> generated by the domain
/// itself (see docs/decisions/0002-guid-identifiers.md), so an aggregate is fully valid before
/// it is persisted and there is no round trip needed to obtain its identifier.
/// </summary>
public abstract class Entity : IEquatable<Entity>
{
    /// <summary>Required by ORM materializers only. Prefer the domain factories.</summary>
    protected Entity()
    {
    }

    protected Entity(Guid id) => Id = id;

    /// <summary>Unique, auto-generated identifier of the entity.</summary>
    public Guid Id { get; protected set; }

    public bool Equals(Entity? other)
        => other is not null
           && other.GetType() == GetType()
           && other.Id != Guid.Empty
           && other.Id == Id;

    public override bool Equals(object? obj) => Equals(obj as Entity);

    public override int GetHashCode() => HashCode.Combine(GetType(), Id);

    public static bool operator ==(Entity? left, Entity? right) => Equals(left, right);

    public static bool operator !=(Entity? left, Entity? right) => !Equals(left, right);
}
